with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , REJECTION_REASON as SUBMISSION_REJECTION_REASON
        , DEFICIENCY_REASON as SUBMISSION_DEFICIENCY_REASON
        , REFERAL_REASON as UNDERWRITER_REFERRAL_REASON
        , cast(null as varchar) as REFERRED_BY_USER_REFERENCE
        , cast(null as varchar) as REFERRAL_DATE
        , cast(null as varchar) as REFERRED_BY_RULE_ENGINE_INDICATOR
        , 'BA_CCP_SUB_MATER_DTLS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ba_ccp_sub_mater_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as SUBMISSION_REJECTION_REASON
        , cast(null as varchar) as SUBMISSION_DEFICIENCY_REASON
        , REFERRAL_REASON as UNDERWRITER_REFERRAL_REASON
        , REFER_BY as REFERRED_BY_USER_REFERENCE
        , REFER_DATE as REFERRAL_DATE
        , REFERED_BY_RULE_ENGINE as REFERRED_BY_RULE_ENGINE_INDICATOR
        , 'BJAZ_POLICY_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_bases_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SUBMISSION_REJECTION_REASON end) as SUBMISSION_REJECTION_REASON,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SUBMISSION_DEFICIENCY_REASON end) as SUBMISSION_DEFICIENCY_REASON,
        max(case when SOURCE_RUN = 'opus_health_delta3' then UNDERWRITER_REFERRAL_REASON end) as UNDERWRITER_REFERRAL_REASON,
        max(case when SOURCE_RUN = 'opus_health_delta3' then REFERRED_BY_USER_REFERENCE end) as REFERRED_BY_USER_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then REFERRAL_DATE end) as REFERRAL_DATE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then REFERRED_BY_RULE_ENGINE_INDICATOR end) as REFERRED_BY_RULE_ENGINE_INDICATOR,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when SUBMISSION_REJECTION_REASON is not null or SUBMISSION_DEFICIENCY_REASON is not null or UNDERWRITER_REFERRAL_REASON is not null or REFERRED_BY_USER_REFERENCE is not null or REFERRAL_DATE is not null or REFERRED_BY_RULE_ENGINE_INDICATOR is not null
                     then md5(upper(coalesce(cast(SUBMISSION_REJECTION_REASON as varchar), '') || '|' || coalesce(cast(SUBMISSION_DEFICIENCY_REASON as varchar), '') || '|' || coalesce(cast(UNDERWRITER_REFERRAL_REASON as varchar), '') || '|' || coalesce(cast(REFERRED_BY_USER_REFERENCE as varchar), '') || '|' || coalesce(cast(REFERRAL_DATE as varchar), '') || '|' || coalesce(cast(REFERRED_BY_RULE_ENGINE_INDICATOR as varchar), '')))
                end as SAT_POLICY_LIFECYCLE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_LIFECYCLE_HASHDIFF is not null
